// UnaryEndpoint is the basic client-side unary call endpoint type.
type UnaryEndpoint = endpoint.Endpoint

// StreamEndpoint defines the client-side streaming call endpoint signature.
// It receives a context and request, returning a stream interface and optional error.
type StreamEndpoint func(ctx context.Context, req interface{}) (stream interface{}, err error)

// StreamRecvEndpoint represents a client endpoint that only receives from the stream.
type StreamRecvEndpoint func(stream streaming.Stream) error

// EqualsTo checks if two StreamRecvEndpoint instances are functionally equivalent.
func (e StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	// Function pointer comparison - same underlying function
	return &e == &e2
}

// StreamSendEndpoint represents a client endpoint that only sends to the stream.
type StreamSendEndpoint func(stream streaming.Stream) error

// EqualsTo checks if two StreamSendEndpoint instances are functionally equivalent.
func (e StreamSendEndpoint) EqualsTo(e2 StreamSendEndpoint) bool {
	// Function pointer comparison - same underlying function
	return &e == &e2
}
